import { test, expect } from '@playwright/test';

test.describe('Async Form Submission - Disable Submit Button', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should disable submit button while form submission is in progress', async ({ page }) => {
    // Intercept the form submission API call
    await page.route('**/api/submit-form', (route) => {
      route.abort('blockedbyclient');
    });

    // Fill in form fields using getByLabel
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john@example.com');

    const messageInput = page.getByLabel('Message');
    await messageInput.fill('This is a test message');

    // Click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify submit button is disabled
    await expect(submitButton).toBeDisabled();

    // Verify loading state is visible
    const loadingIndicator = page.getByRole('status', { name: /submitting/i });
    await expect(loadingIndicator).toBeVisible();

    // Wait for the async operation to complete
    await page.waitForTimeout(1000);

    // Verify submit button is re-enabled
    await expect(submitButton).not.toBeDisabled();

    // Verify success message is displayed
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should handle form submission failure and re-enable submit button', async ({ page }) => {
    // Intercept the form submission API call and simulate failure
    await page.route('**/api/submit-form', (route) => {
      route.abort('blockedbyclient');
    });

    // Fill in form fields using getByLabel
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Smith');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('jane@example.com');

    const messageInput = page.getByLabel('Message');
    await messageInput.fill('Another test message');

    // Click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify submit button is disabled
    await expect(submitButton).toBeDisabled();

    // Verify loading state is visible
    const loadingIndicator = page.getByRole('status', { name: /submitting/i });
    await expect(loadingIndicator).toBeVisible();

    // Wait for the async operation to complete
    await page.waitForTimeout(1000);

    // Verify submit button is re-enabled
    await expect(submitButton).not.toBeDisabled();

    // Verify error message is displayed
    const errorMessage = page.getByText('Submission failed');
    await expect(errorMessage).toBeVisible();

    // Verify form fields are still populated
    await expect(nameInput).toHaveValue('Jane Smith');
  });
});
